import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        new Main().process();
    }

    void process() {
        InputReader in = new InputReader(System.in);
        OutputWriter out = new OutputWriter(System.out);
        Solver s = new Solver();
        s.execute(1, in, out);
        out.close();
    }

    static class Solver {
        private static final long MOD = 1000000007L;
        private static final long INF = (long)1e18 + 1;
        private long[][] binomial = new long[100][100];

        private long compute(long base, int n1, int r1, int n2, int r2) {
            base = (base * binomial[n1][r1]) % MOD;
            base = (base * binomial[n2][r2]) % MOD;
            return base;
        }

        void execute(int testId, InputReader in, OutputWriter out) {
            int N = in.nextInt();
            int K = in.nextInt();
            int cnt50 = 0, cnt100 = 0;
            for (int i = 0; i < N; i++) {
                int val = in.nextInt();
                if (val == 50) cnt50++;
                else cnt100++;
            }

            // Build binomial table
            for (int i = 0; i < 100; i++) {
                binomial[i][0] = 1;
                for (int j = 1; j <= i; j++) {
                    binomial[i][j] = (binomial[i-1][j] + binomial[i-1][j-1]) % MOD;
                }
            }

            long[][][] distance = new long[200][200][2];
            long[][][] ways = new long[200][200][2];
            for (int i = 0; i < 200; i++) {
                for (int j = 0; j < 200; j++) {
                    Arrays.fill(distance[i][j], INF);
                    Arrays.fill(ways[i][j], 0);
                }
            }

            distance[0][0][0] = 0;
            ways[0][0][0] = 1;

            Deque<Node> queue = new ArrayDeque<>();
            queue.add(new Node(0, 0, 0, 0));

            while (!queue.isEmpty()) {
                Node node = queue.removeFirst();
                int a = node.a;
                int b = node.b;
                int side = node.side;
                long d = distance[a][b][side];

                if (side == 0) {
                    int left50 = cnt50 - a;
                    int left100 = cnt100 - b;
                    for (int take50 = 0; take50 <= left50; take50++) {
                        for (int take100 = 0; take100 <= left100; take100++) {
                            if (take50 == 0 && take100 == 0) continue;
                            int weight = take50 * 50 + take100 * 100;
                            if (weight > K) break;
                            int na = a + take50;
                            int nb = b + take100;
                            int nextSide = side ^ 1;
                            if (distance[na][nb][nextSide] >= d + 1) {
                                if (distance[na][nb][nextSide] > d + 1) {
                                    distance[na][nb][nextSide] = d + 1;
                                    queue.addLast(new Node(na, nb, nextSide, d + 1));
                                    ways[na][nb][nextSide] = (ways[na][nb][nextSide] + compute(ways[a][b][side], left50, take50, left100, take100)) % MOD;
                                } else {
                                    ways[na][nb][nextSide] = (ways[na][nb][nextSide] + compute(ways[a][b][side], left50, take50, left100, take100)) % MOD;
                                }
                            }
                        }
                    }
                } else {
                    int left50 = a;
                    int left100 = b;
                    for (int take50 = 0; take50 <= left50; take50++) {
                        for (int take100 = 0; take100 <= left100; take100++) {
                            if (take50 == 0 && take100 == 0) continue;
                            int weight = take50 * 50 + take100 * 100;
                            if (weight > K) break;
                            int na = a - take50;
                            int nb = b - take100;
                            int nextSide = side ^ 1;
                            if (distance[na][nb][nextSide] >= d + 1) {
                                if (distance[na][nb][nextSide] > d + 1) {
                                    distance[na][nb][nextSide] = d + 1;
                                    queue.addLast(new Node(na, nb, nextSide, d + 1));
                                    ways[na][nb][nextSide] = (ways[na][nb][nextSide] + compute(ways[a][b][side], left50, take50, left100, take100)) % MOD;
                                } else {
                                    ways[na][nb][nextSide] = (ways[na][nb][nextSide] + compute(ways[a][b][side], left50, take50, left100, take100)) % MOD;
                                }
                            }
                        }
                    }
                }
            }

            if (distance[cnt50][cnt100][1] == INF) {
                out.println(-1);
            } else {
                out.println(distance[cnt50][cnt100][1]);
            }
            out.println(ways[cnt50][cnt100][1]);
        }

        static class Node {
            int a, b, side;
            long dist;
            Node(int a, int b, int side, long dist) {
                this.a = a;
                this.b = b;
                this.side = side;
                this.dist = dist;
            }
        }
    }

    static class InputReader {
        private final InputStream in;
        private final byte[] buffer = new byte[1024];
        private int index = 0, size = 0;

        public InputReader(InputStream stream) {
            in = stream;
        }

        private int fetch() {
            if (size == -1) throw new RuntimeException();
            if (index >= size) {
                index = 0;
                try { size = in.read(buffer); } catch (IOException e) { throw new RuntimeException(); }
                if (size <= 0) return -1;
            }
            return buffer[index++];
        }

        public int nextInt() {
            int c;
            while ((c = fetch()) <= ' ') {}
            int num = 0;
            do {
                num = num * 10 + (c - '0');
            } while ((c = fetch()) > ' ');
            return num;
        }
    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream stream) {
            writer = new PrintWriter(stream);
        }

        public void println(long value) {
            writer.println(value);
        }

        public void close() {
            writer.close();
        }
    }
}
